package org.millenaire.common.entity;import net.minecraft.world.item.*;import net.minecraft.world.entity.*;import org.millenaire.common.utilities.Point;import org.millenaire.common.village.Building;import java.util.*;public class MillVillager extends Entity {public Point destination;public Building hall;public String goalKey;public boolean rejectWrite;public int dyes,swings;public Map<org.millenaire.common.goal.Goal,Long> lastGoalTime;public MillVillager(){super(EntityType.PIG,null);}protected void defineSynchedData(){}protected void readAdditionalSaveData(net.minecraft.nbt.CompoundTag t){}protected void addAdditionalSaveData(net.minecraft.nbt.CompoundTag t){}public net.minecraft.network.protocol.Packet<?> getAddEntityPacket(){return null;}public Point getGoalDestPoint(){return destination;}public Building getTownHall(){return hall;}public ItemStack[] getBestShovelStack(){return new ItemStack[]{new ItemStack(Items.IRON_SHOVEL)};}public boolean setBlockstate(Point p,net.minecraft.world.level.block.state.BlockState s){if(rejectWrite)return false;p.state=s;return true;}public void swing(net.minecraft.world.InteractionHand h){swings++;}public void addToInv(Item i,int n){if(i!=Items.PURPLE_DYE)throw new AssertionError("Wrong dye");dyes+=n;}}